    t1_title: "Mediterrán növények",
    t1_text: "A mediterrán éghajlat tökéletes a napsütést kedvelő növények számára, amelyek túlélik a száraz nyarakat. Az olajbogyó, a szőlő és a citrusfélék nagyon gyakoriak itt.",
